/* Stub for empty menus (e.g., "(No recent destinations)") */
&.stub-menuitem {
  --menuitem-icon: var(--icon-info);
}

&::part(icon),
& > .menu-icon {
  content: var(--menuitem-icon);
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;
}
